-- Migration: Create nodes and edges tables for lineage tree

CREATE TABLE IF NOT EXISTS nodes (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  title TEXT,
  description TEXT,
  scripture_reference TEXT,
  scripture_text TEXT,
  lineage TEXT CHECK(lineage IN ('main', 'royal', 'biological')),
  epoch TEXT,
  x REAL,
  y REAL
);

CREATE TABLE IF NOT EXISTS edges (
  id TEXT PRIMARY KEY,
  source TEXT NOT NULL,
  target TEXT NOT NULL,
  FOREIGN KEY (source) REFERENCES nodes(id),
  FOREIGN KEY (target) REFERENCES nodes(id)
);

CREATE INDEX IF NOT EXISTS idx_nodes_lineage ON nodes(lineage);
CREATE INDEX IF NOT EXISTS idx_nodes_epoch ON nodes(epoch);
CREATE INDEX IF NOT EXISTS idx_edges_source ON edges(source);
CREATE INDEX IF NOT EXISTS idx_edges_target ON edges(target);

